package org.sleepwell.app;
import android.app.Activity;import android.app.Dialog;import android.view.*;import android.content.Intent;import android.os.Bundle;import android.widget.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;import org.json.*;
/** A private draft. Use dates returns to the alarm editor; only Save alarm persists/schedules. */
public final class AlarmExcludedDatesActivity extends Activity {
 static final int REQUEST=687;private final SortedSet<LocalDate> dates=new TreeSet<>();private String request,error="";private RecordCalendar calendar;private Dialog details;
 static Intent edit(Activity activity,Alarm alarm,String request){return RecordUi.intent(activity,AlarmExcludedDatesActivity.class).putExtra("request",request).putExtra("dates",AlarmExcludedDates.encode(alarm.excludedDates).toString()).putExtra("invalid",alarm.excludedDatesInvalid);}
 @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);request=getIntent().getStringExtra("request");if(!BackupRuntime.nonce(request)){finish();return;}try{dates.addAll(AlarmExcludedDates.read(new JSONArray(state==null?getIntent().getStringExtra("dates"):state.getString("dates","[]"))));}catch(Exception invalid){error="Saved date selection could not be read. Review a new selection or cancel.";}if(getIntent().getBooleanExtra("invalid",false)&&state==null)error="Saved skipped dates need review. Use a new selection to replace them.";if(state!=null)error=state.getString("error",error);render();if(state!=null&&state.containsKey("calendar"))openCalendar(state.getBundle("calendar"));}
 private void render(){
  LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.menuAction(RecordUi.header(body,"Skip selected dates",this::finish),"Skipped date options",this::about,false);Design.space(body,12);
  Design.text(body,"Skip this alarm on the dates you choose.",14,400,Design.MUTED);Design.space(body,20);Design.text(body,dates.size()+" of "+AlarmExcludedDates.LIMIT+" dates selected",13,500,Design.MUTED);Design.space(body,10);
  if(dates.isEmpty()){LinearLayout empty=Design.col(this);Design.pad(empty,16,24);empty.setGravity(Gravity.CENTER);empty.setBackground(Design.shape(this,Design.SOFT,18));empty.addView(new Design.Icon(this,"calendar",Design.BROWN),new LinearLayout.LayoutParams(Design.dp(this,36),Design.dp(this,36)));Design.space(empty,12);Design.text(empty,"No dates selected",19,600,Design.INK).setGravity(Gravity.CENTER);Design.space(empty,6);Design.text(empty,"Add a day off for this alarm.",13,400,Design.MUTED).setGravity(Gravity.CENTER);body.addView(empty);}
  LocalDate today=LocalDate.now();for(LocalDate date:dates){LinearLayout row=Design.row(this);row.setMinimumHeight(Design.dp(this,56));LinearLayout copy=Design.col(this);Design.text(copy,date.format(DateTimeFormatter.ofPattern("EEE, d MMM uuuu",Locale.getDefault())),15,500,Design.INK);if(date.isBefore(today))Design.text(copy,"Passed · no future effect",11,400,Design.MUTED);row.addView(copy,new LinearLayout.LayoutParams(0,-2,1));row.addView(Design.iconButton(this,"close","Remove skipped date "+date,()->{dates.remove(date);error="";render();}),new LinearLayout.LayoutParams(Design.dp(this,48),Design.dp(this,48)));body.addView(row);Design.line(body);}
  Design.space(body,14);Button add=Design.button(body,"Add date",false,()->openCalendar(null));RecordUi.enabled(add,dates.size()<AlarmExcludedDates.LIMIT);if(!dates.isEmpty())Design.button(body,"Clear selected dates",false,()->{dates.clear();error="";render();});
  LinearLayout footer=RecordUi.footer(body);if(!error.isEmpty()){TextView issue=Design.text(footer,error,13,500,NightDialTokens.NEGATIVE);issue.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);Design.space(footer,8);}Design.text(footer,"Save alarm applies these dates.",12,400,Design.MUTED);Design.space(footer,6);Design.button(footer,"Use dates",true,()->{setResult(RESULT_OK,new Intent().putExtra("request",request).putExtra("dates",AlarmExcludedDates.encode(dates).toString()));finish();});Design.button(footer,"Cancel",false,this::finish);
 }
 private void about(){if(details!=null)details.dismiss();details=SleepPicker.message(this,"How skipped dates work","These dates apply only to this alarm, in the phone’s local time zone. Ordinary and sunrise occurrences on these dates are skipped. This is your selection, not an automatic public-holiday calendar.\n\nAdd today or a future date within two years, up to 64 dates. Changing the alarm time or repeat days keeps this list. Past dates have no future effect.\n\nCurrent snoozes and ringing alarms stay unchanged. Use dates returns this selection to the draft; Save alarm applies it.");}
 private void openCalendar(Bundle saved){if(calendar!=null)calendar.close();LocalDate today=LocalDate.now();calendar=new RecordCalendar(this,"Add skipped date",today,saved,date->{LocalDate current=LocalDate.now();if(date.isBefore(current)||date.isAfter(current.plusYears(2))){error="Choose today or a date within the next two years.";}else if(dates.size()>=AlarmExcludedDates.LIMIT&&!dates.contains(date)){error="Use at most 64 dates.";}else if(!dates.add(date)){error="That date is already selected.";}else error="";render();},null);}
 @Override public void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putString("dates",AlarmExcludedDates.encode(dates).toString());out.putString("error",error);if(calendar!=null&&calendar.showing())out.putBundle("calendar",calendar.state());}
 @Override protected void onDestroy(){if(calendar!=null)calendar.close();if(details!=null)details.dismiss();super.onDestroy();}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
